import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth, LANG_LIST } from '../App';

const navGroups = [
  { label: 'Overview', items: [
    { path: '/dashboard',      icon: '▦',  label: 'Dashboard' },
    { path: '/agents',         icon: '🧠', label: 'AI Agents' },
  ]},
  { label: 'Intelligence', items: [
    { path: '/recommendations',icon: '🌱', label: 'Crop Prediction' },
    { path: '/market',         icon: '📈', label: 'Market Trends' },
    { path: '/disease-scanner',icon: '🔬', label: 'Disease Scanner' },
  ]},
  { label: 'Farm Tools', items: [
    { path: '/weather',        icon: '🌤', label: 'Weather Alerts' },
    { path: '/water',          icon: '💧', label: 'Water Management' },
    { path: '/fertilizer',     icon: '🧪', label: 'Fertilizer Guide' },
    { path: '/sustainability',  icon: '♻️', label: 'Sustainability' },
  ]},
  { label: 'Assistant', items: [
    { path: '/chatbot',        icon: '🤖', label: 'KisanGPT' },
    { path: '/select-language',icon: '🌐', label: 'Change Language' },
  ]},
];

export default function Sidebar({ open, onClose }) {
  const navigate = useNavigate();
  const location = useLocation();
  const { user, setUser, lang, setLang, darkMode, setDarkMode } = useAuth();
  const currentLang = LANG_LIST.find(l => l.code === lang);

  const go = (path) => { navigate(path); onClose?.(); };

  return (
    <>
      {open && (
        <div className="fixed inset-0 bg-black/40 z-30 lg:hidden" onClick={onClose} />
      )}
      <aside
        className={`fixed top-0 left-0 h-full w-60 z-40 sidebar flex flex-col transition-transform duration-300
          ${open ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0`}
      >
        {/* Logo */}
        <div className="px-5 py-4 border-b border-slate-100 flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-lg btn-primary flex items-center justify-center text-base">🌿</div>
            <div>
              <div className="font-display font-bold text-slate-800 text-sm leading-tight">SmartSheti AI</div>
              <div className="text-brand-600 text-xs font-medium">Smart Farming</div>
            </div>
          </div>
          <button
            onClick={() => setDarkMode(d => !d)}
            className="w-7 h-7 rounded-lg border border-slate-200 flex items-center justify-center text-xs hover:bg-slate-50 transition-colors"
            title="Toggle theme"
          >
            {darkMode ? '☀️' : '🌙'}
          </button>
        </div>

        {/* Nav */}
        <nav className="flex-1 px-3 py-2 overflow-y-auto">
          {navGroups.map(group => (
            <div key={group.label}>
              <div className="sidebar-group-label">{group.label}</div>
              {group.items.map(item => (
                <button
                  key={item.path}
                  onClick={() => go(item.path)}
                  className={`sidebar-link ${location.pathname === item.path ? 'active' : ''}`}
                >
                  <span className="text-base w-5 text-center leading-none">{item.icon}</span>
                  <span>{item.label}</span>
                </button>
              ))}
            </div>
          ))}
        </nav>

        {/* Language picker */}
        <div className="px-4 py-3 border-t border-slate-100">
          <div className="text-xs font-600 text-slate-400 uppercase tracking-wider mb-1.5">Language</div>
          <div className="flex items-center gap-2">
            <select
              value={lang}
              onChange={e => setLang(e.target.value)}
              className="flex-1 text-xs px-2.5 py-1.5 rounded-lg border border-slate-200 bg-white text-slate-700"
            >
              {LANG_LIST.map(l => (
                <option key={l.code} value={l.code}>{l.flag} {l.native}</option>
              ))}
            </select>
          </div>
        </div>

        {/* User */}
        <div className="px-4 py-3 border-t border-slate-100">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-brand-600 flex items-center justify-center text-white font-bold text-sm flex-shrink-0">
              {user?.name?.[0]?.toUpperCase() || 'F'}
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-slate-800 text-sm font-semibold truncate">{user?.name || 'Farmer'}</div>
              <div className="text-slate-400 text-xs truncate">{user?.state || 'India'} · {user?.acres || '5'} acres</div>
            </div>
            <button
              onClick={() => setUser(null)}
              className="text-slate-400 hover:text-red-500 text-sm transition-colors"
              title="Logout"
            >⏻</button>
          </div>
        </div>
      </aside>
    </>
  );
}
